using System;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Console input for VEIN: the server reads no console input and has no RCON, so the commands typed in the panel's
// console go to its HTTP API (status, players, messages to the players, save).
// The server's HTTP API (Game.ini HTTPPort): it listens on the loopback address only, so the panel reaches it from the monitor
// of the server that hosts the service. Routes: GET /status /players /players/<id> /characters/<id> /time /weather,
// POST /notification {"Message": ...} /save /saveandexit.
async Task<(int Status, string Body)> VeinHttp(string method, string path, string json, int timeoutMs)
{
    int port;
    try { port = Convert.ToInt32(ThisService.Ports["HttpPort"]); }
    catch { throw new Exception("The service has no HttpPort."); }
    using (var http = new HttpClient { Timeout = TimeSpan.FromMilliseconds(timeoutMs) })
    {
        var url = "http://" + System.Net.IPAddress.Loopback + ":" + port + "/" + path.TrimStart('/');
        var request = new HttpRequestMessage(method == "POST" ? HttpMethod.Post : HttpMethod.Get, url);
        if (method == "POST")
        {
            // The server reads a JSON body as a C string: without a terminating NUL it answers {"error": "bad_body"}.
            var content = new ByteArrayContent(Encoding.UTF8.GetBytes(string.IsNullOrEmpty(json) ? "" : json + "\0"));
            content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/json");
            request.Content = content;
        }
        using (var response = await http.SendAsync(request, ThisCancellationToken))
            return ((int)response.StatusCode, await response.Content.ReadAsStringAsync());
    }
}


const string help = "Commands: status | players | player <SteamID64> | character <id> | time | weather | say <message> | save | saveandexit";

string Pretty(string body)
{
    try { return JsonSerializer.Serialize(JsonDocument.Parse(body).RootElement, new JsonSerializerOptions { WriteIndented = true }); }
    catch { return body; }
}

string result;
try
{
    var line = (Globals.Variables.Parse<string>("Command") ?? string.Empty).Trim();
    var space = line.IndexOf(' ');
    var verb = (space < 0 ? line : line.Substring(0, space)).ToLowerInvariant();
    var arg = space < 0 ? "" : line.Substring(space + 1).Trim();
    (int Status, string Body) reply;
    switch (verb)
    {
        case "":
            result = string.Empty;
            break;
        case "help":
        case "?":
            result = help;
            break;
        case "status":
        case "players":
        case "time":
        case "weather":
            reply = await VeinHttp("GET", verb, null, 8000);
            result = reply.Status == 200 ? Pretty(reply.Body) : "HTTP " + reply.Status + " " + reply.Body;
            break;
        case "player":
        case "character":
            if (arg.Length == 0) { result = "Usage: " + verb + " <id>"; break; }
            reply = await VeinHttp("GET", (verb == "player" ? "players/" : "characters/") + Uri.EscapeDataString(arg), null, 8000);
            result = reply.Status == 200 ? Pretty(reply.Body) : "HTTP " + reply.Status + " " + reply.Body;
            break;
        case "say":
        case "notify":
        case "broadcast":
            if (arg.Length == 0) { result = "Usage: say <message>"; break; }
            reply = await VeinHttp("POST", "notification", JsonSerializer.Serialize(new { Message = arg }), 8000);
            result = reply.Status < 300 ? "Sent to the players: " + arg : "HTTP " + reply.Status + " " + reply.Body;
            break;
        case "save":
            reply = await VeinHttp("POST", "save", "", 60000);
            result = reply.Status < 300 ? "The world is being saved." : "HTTP " + reply.Status + " " + reply.Body;
            break;
        case "saveandexit":
            reply = await VeinHttp("POST", "saveandexit", "", 60000);
            result = reply.Status < 300 ? "The server saves the world and exits." : "HTTP " + reply.Status + " " + reply.Body;
            break;
        default:
            result = "Unknown command '" + verb + "'. " + help;
            break;
    }
}
catch (Exception ex)
{
    result = "The server's HTTP API did not answer (" + ex.Message + "). It starts after the map has loaded.";
}
Globals.ReturnValue = result;

