// Graceful stop: asks the server to save the world and exit (HTTP API POST /saveandexit) and waits until it is gone.
// When the API does not answer (the map is still loading: nothing to save yet), Linux gets a SIGINT, which makes the
// engine exit cleanly without saving.
// Then the config settings edited in the panel while the server ran are written again (the server overwrites its
// ini files on exit). Only the server process of THIS service is touched.
// The server's HTTP API (Game.ini HTTPPort): it listens on the loopback address only, so the panel reaches it from the monitor
// of the server that hosts the service. Routes: GET /status /players /players/<id> /characters/<id> /time /weather,
// POST /notification {"Message": ...} /save /saveandexit.
async Task<(int Status, string Body)> VeinHttp(string method, string path, string json, int timeoutMs)
{
    int port;
    try { port = Convert.ToInt32(ThisService.Ports["HttpPort"]); }
    catch { throw new Exception("The service has no HttpPort."); }
    using (var http = new HttpClient { Timeout = TimeSpan.FromMilliseconds(timeoutMs) })
    {
        var url = "http://" + System.Net.IPAddress.Loopback + ":" + port + "/" + path.TrimStart('/');
        var request = new HttpRequestMessage(method == "POST" ? HttpMethod.Post : HttpMethod.Get, url);
        if (method == "POST")
        {
            // The server reads a JSON body as a C string: without a terminating NUL it answers {"error": "bad_body"}.
            var content = new ByteArrayContent(Encoding.UTF8.GetBytes(string.IsNullOrEmpty(json) ? "" : json + "\0"));
            content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/json");
            request.Content = content;
        }
        using (var response = await http.SendAsync(request, ThisCancellationToken))
            return ((int)response.StatusCode, await response.Content.ReadAsStringAsync());
    }
}

// The server writes its Game.ini and Engine.ini (console variables) back from memory when it exits, so a config edit
// made while it runs would be lost. While the server runs, the config-file write events record what each panel edit
// changed (.tca/vein-pending-<file>.json); after the server has exited, the stop script writes those keys again.
const string veinBinaryLinux = "VeinServer-Linux-Test";
const string veinBinaryWindows = "VeinServer-Win64-Test";

string VeinRoot() => Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;

List<int> VeinServerPids()
{
    var root = VeinRoot();
    var pids = new List<int>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var p in Process.GetProcessesByName(veinBinaryWindows))
        {
            try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) pids.Add(p.Id); }
            catch { } // exited meanwhile
        }
        return pids;
    }
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var exe = new FileInfo(Path.Combine(dir, "exe")).LinkTarget ?? "";
            if (exe.StartsWith(root, StringComparison.Ordinal) && Path.GetFileName(exe) == veinBinaryLinux) pids.Add(pid);
        }
        catch { } // processes of other users, or gone meanwhile
    }
    pids.Sort();
    return pids;
}

string VeinStateDir() => Path.Combine(VeinRoot(), ".tca");
string VeinPendingPath(string configFile) => Path.Combine(VeinStateDir(), "vein-pending-" + Path.GetFileName(configFile) + ".json");
string VeinBeforePath(string configFile) => Path.Combine(VeinStateDir(), "vein-before-" + Path.GetFileName(configFile));
string[] VeinConfigFiles()
{
    var folder = Path.Combine(VeinRoot(), "Vein", "Saved", "Config", System.OperatingSystem.IsWindows() ? "WindowsServer" : "LinuxServer");
    return new[] { Path.Combine(folder, "Game.ini"), Path.Combine(folder, "Engine.ini") };
}

// "Section|Key" of an ini line ("" for blank lines, comments and section headers). +Key/-Key/.Key/!Key (array
// operations) belong to Key.
string IniKey(string section, string line)
{
    var t = line.Trim();
    if (t.Length == 0 || t[0] == ';' || t[0] == '#' || t[0] == '[') return "";
    var eq = t.IndexOf('=');
    var key = (eq < 0 ? t : t.Substring(0, eq)).Trim().TrimStart('+', '-', '.', '!').Trim();
    return key.Length == 0 ? "" : section + "|" + key;
}

string IniSection(string line)
{
    var t = line.Trim();
    return t.Length > 2 && t[0] == '[' && t[t.Length - 1] == ']' ? t.Substring(1, t.Length - 2).Trim() : null;
}

List<string> IniLines(string text) => text.Replace("\r\n", "\n").Split('\n').ToList();

// Every key with all of its lines, in file order.
Dictionary<string, List<string>> IniEntries(string text)
{
    var entries = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
    var section = "";
    foreach (var line in IniLines(text))
    {
        var s = IniSection(line);
        if (s != null) { section = s; continue; }
        var key = IniKey(section, line);
        if (key == "") continue;
        if (!entries.TryGetValue(key, out var list)) entries[key] = list = new List<string>();
        list.Add(line.Trim());
    }
    return entries;
}

// Replaces the lines of each key in the file with the given lines (an empty list removes the key).
string IniApply(string text, Dictionary<string, List<string>> changes)
{
    var lines = IniLines(text);
    foreach (var change in changes)
    {
        var want = change.Key.Substring(0, change.Key.IndexOf('|'));
        var section = "";
        var matches = new List<int>();
        var lastInSection = -1;
        var header = -1;
        for (var i = 0; i < lines.Count; i++)
        {
            var s = IniSection(lines[i]);
            if (s != null)
            {
                section = s;
                if (header < 0 && s.Equals(want, StringComparison.OrdinalIgnoreCase)) header = i;
                continue;
            }
            if (!section.Equals(want, StringComparison.OrdinalIgnoreCase)) continue;
            if (lines[i].Trim().Length > 0) lastInSection = i;
            if (string.Equals(IniKey(section, lines[i]), change.Key, StringComparison.OrdinalIgnoreCase)) matches.Add(i);
        }
        if (matches.Count > 0)
        {
            for (var m = matches.Count - 1; m >= 0; m--) lines.RemoveAt(matches[m]);
            lines.InsertRange(matches[0], change.Value);
        }
        else if (change.Value.Count == 0) continue;
        else if (lastInSection >= 0) lines.InsertRange(lastInSection + 1, change.Value);
        else if (header >= 0) lines.InsertRange(header + 1, change.Value);
        else
        {
            while (lines.Count > 0 && lines[lines.Count - 1].Trim().Length == 0) lines.RemoveAt(lines.Count - 1);
            lines.Add("");
            lines.Add("[" + want + "]");
            lines.AddRange(change.Value);
            lines.Add("");
        }
    }
    return string.Join(Environment.NewLine, lines);
}

Dictionary<string, List<string>> VeinReadPending(string configFile)
{
    var path = VeinPendingPath(configFile);
    if (!File.Exists(path)) return new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
    var read = JsonSerializer.Deserialize<Dictionary<string, List<string>>>(File.ReadAllText(path));
    return new Dictionary<string, List<string>>(read ?? new Dictionary<string, List<string>>(), StringComparer.OrdinalIgnoreCase);
}

// After the server exited: writes the keys edited while it ran into the file it wrote on exit.
void VeinApplyPending()
{
    foreach (var file in VeinConfigFiles())
    {
        var pendingPath = VeinPendingPath(file);
        if (!File.Exists(pendingPath)) continue;
        var pending = VeinReadPending(file);
        if (pending.Count > 0 && File.Exists(file))
        {
            File.WriteAllText(file, IniApply(File.ReadAllText(file), pending));
            ScriptConsole.WriteLine((object)("Applied " + pending.Count + " setting(s) edited while the server was running to " + Path.GetFileName(file) + "."));
        }
        File.Delete(pendingPath);
    }
}

void VeinClearPending()
{
    foreach (var file in VeinConfigFiles())
    {
        if (File.Exists(VeinPendingPath(file))) File.Delete(VeinPendingPath(file));
        if (File.Exists(VeinBeforePath(file))) File.Delete(VeinBeforePath(file));
    }
}


const int maxWaitSeconds = 120;

var targets = VeinServerPids();
if (targets.Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    VeinApplyPending();
    return;
}

var asked = false;
try
{
    var reply = await VeinHttp("POST", "saveandexit", "", 30000);
    asked = reply.Status < 300;
    ScriptConsole.WriteLine((object)(asked ? "Asked the server to save the world and exit." : "The HTTP API answered " + reply.Status + "."));
}
catch (Exception ex)
{
    ScriptConsole.WriteLine((object)("The server's HTTP API did not answer (" + ex.Message + ")."));
}
if (!asked && !System.OperatingSystem.IsWindows())
{
    using (var kill = Process.Start(new ProcessStartInfo("kill", new[] { "-INT", targets[0].ToString() }) { UseShellExecute = false }))
        kill.WaitForExit();
    ScriptConsole.WriteLine((object)"Sent SIGINT to the server.");
    asked = true;
}
if (!asked) return;

for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (!VeinServerPids().Any(targets.Contains))
    {
        ScriptConsole.WriteLine((object)("The server exited after " + second + " s."));
        VeinApplyPending();
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));

