var root = (string)ThisService.RootDirectory;
// crashpad_handler (the Sentry crash reporter) needs it too: when the server cannot start it, the forked child
// deadlocks in the engine's crash handler and the server hangs at startup, before the map loads.
foreach (var binary in new[] { Path.Combine(root, "Vein", "Binaries", "Linux", "VeinServer-Linux-Test"),
                               Path.Combine(root, "Vein", "Plugins", "Sentry", "Binaries", "Linux", "crashpad_handler") })
{
    if (!File.Exists(binary)) continue;
    var mode = File.GetUnixFileMode(binary);
    var wanted = mode | UnixFileMode.UserExecute | UnixFileMode.GroupExecute;
    if (mode != wanted)
    {
        File.SetUnixFileMode(binary, wanted);
        ScriptConsole.WriteLine((object)("Made " + Path.GetFileName(binary) + " executable."));
    }
}

var steamDir = Path.Combine(root, ".steam");
var sdk = Path.Combine(steamDir, "sdk64");
var target = Path.Combine(sdk, "steamclient.so");
