const string cdn = "https://media.steampowered.com/client/";
using (var http = new HttpClient { Timeout = TimeSpan.FromMinutes(10) })
{
    var manifest = await http.GetStringAsync(cdn + "steam_cmd_linux", ThisCancellationToken);
    var block = Regex.Match(manifest, "\"steamcmd_bins_linux\"\\s*\\{(?<b>[^}]*)\\}");
    var file = Regex.Match(block.Groups["b"].Value, "\"file\"\\s*\"(?<v>[^\"]+)\"").Groups["v"].Value;
    var sha = Regex.Match(block.Groups["b"].Value, "\"sha2\"\\s*\"(?<v>[0-9a-fA-F]{64})\"").Groups["v"].Value;
    if (file == "" || sha == "") throw new Exception("The SteamCMD package list has no steamcmd_bins_linux entry; copy a SteamCMD linux64/steamclient.so to .steam/sdk64/ in the service folder.");

    ScriptConsole.WriteLine((object)"Downloading steamclient.so (SteamCMD binaries, about 40 MB)...");
    var zipBytes = await http.GetByteArrayAsync(cdn + file, ThisCancellationToken);
    if (!Convert.ToHexString(SHA256.HashData(zipBytes)).Equals(sha, StringComparison.OrdinalIgnoreCase))
        throw new Exception("The downloaded SteamCMD package does not match its checksum.");
    using (var zip = new ZipArchive(new MemoryStream(zipBytes)))
    {
        var entry = zip.GetEntry("linux64/steamclient.so") ?? throw new Exception("linux64/steamclient.so is not in the SteamCMD package.");
        Directory.CreateDirectory(sdk);
        var temp = target + ".tmp";
        entry.ExtractToFile(temp, true);
        File.Move(temp, target, true);
    }
}
